look.customCSS:
/* ───── 港风旧梦 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/120px 120px,url("data:image/svg+xml;base64,") center top/cover no-repeat,#14100D !important}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
/* 右下竖排红字，贴着屏幕不跟着滚 */
[data-wk="body"]::after{content:"" !important;position:fixed !important;right:10px !important;bottom:calc(var(--app-safe-bottom, 0px) + 150px) !important;width:50px !important;height:166px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;z-index:-1 !important;opacity:.75 !important}

/* 顶栏：墨黑，左上一颗会闪的红点 REC，名字后面一行斜体 Midnight Romance；下沿一道金色点线 */
[data-wk="chathead"]{background:#14100D !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;overflow:visible !important;gap:6px !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:2px !important;background:radial-gradient(circle,#8C7148 .9px,transparent 1.2px) 0 0/5px 2px repeat-x !important;pointer-events:none !important}
[data-wk="chathead"]::before{content:"REC" !important;position:absolute !important;left:16px !important;top:calc(var(--app-safe-top, 0px) + 2px) !important;font:600 9px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.18em !important;color:#EDE2CF !important;padding-left:10px !important;background:radial-gradient(circle,#E0353A 3px,transparent 3.5px) left center/7px 7px no-repeat !important;animation:hkRec 1.6s steps(1) infinite !important;pointer-events:none !important}
@keyframes hkRec{0%{background-size:7px 7px}50%{background-size:0 0}}
[data-wk="headink"],[data-wk="headink"] *{color:#EDE2CF !important;letter-spacing:.12em !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;white-space:nowrap !important}
[data-wk="headname"] > [data-wk="headink"]::after{content:"Midnight Romance" !important;margin-left:10px !important;font:italic 400 12px/1 Georgia,"Times New Roman",serif !important;letter-spacing:.04em !important;color:#EDE2CF !important;opacity:.85 !important}
[data-wk="headdim"]{color:#9C8E78 !important;white-space:nowrap !important;letter-spacing:.2em !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#EDE2CF !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:32px !important;min-width:32px !important;height:32px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/30px no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/30px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:4px !important}

/* 头像：方的，外面两只取景框角 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:0 !important;box-shadow:none !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:0 !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-6px !important;background:linear-gradient(#EDE2CF,#EDE2CF) left top/8px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) left top/1.4px 8px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/8px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/1.4px 8px no-repeat !important;pointer-events:none !important;border:none !important;border-radius:0 !important;z-index:2 !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"])::before{content:"" !important;position:absolute !important;left:-5px !important;top:50% !important;width:46px !important;height:46px !important;margin-top:-23px !important;background:linear-gradient(#EDE2CF,#EDE2CF) left top/8px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) left top/1.4px 8px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/8px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/1.4px 8px no-repeat !important;pointer-events:none !important;z-index:2 !important}

/* 气泡：直角块，外面两只取景框角。我的话＝暗红块右边一道亮红条；他的话＝墨褐块左边一道金条 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:0 !important;box-shadow:none !important;color:#EDE2CF !important;letter-spacing:.08em !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;inset:-7px !important;background:linear-gradient(#8C7148,#8C7148) left top/9px 1.4px no-repeat,linear-gradient(#8C7148,#8C7148) left top/1.4px 9px no-repeat,linear-gradient(#8C7148,#8C7148) right bottom/9px 1.4px no-repeat,linear-gradient(#8C7148,#8C7148) right bottom/1.4px 9px no-repeat !important;pointer-events:none !important;border:none !important;transform:none !important;width:auto !important;height:auto !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#8A2024,#7E1B1E) !important;border:none !important;border-right:3px solid #E0353A !important;box-shadow:0 0 18px rgba(224,53,58,.25) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,#2E2019,#22180F) !important;border:none !important;border-left:3px solid #C9A36A !important;outline:1px solid rgba(201,163,106,.25) !important}

/* 时间：上一行斜体 Tonight，下一行日期；两边一段金色虚线 */
[data-wk="time"]{display:flex !important;justify-content:center !important;background:linear-gradient(90deg,transparent 8%,#8C7148 8%) left center/34% 1px no-repeat,linear-gradient(90deg,#8C7148 92%,transparent 92%) right center/34% 1px no-repeat !important;-webkit-mask:none !important}
[data-wk="time"]{background:repeating-linear-gradient(90deg,#8C7148 0 3px,transparent 3px 6px) left center/30% 1px no-repeat,repeating-linear-gradient(90deg,#8C7148 0 3px,transparent 3px 6px) right center/30% 1px no-repeat !important}
[data-wk="time"] > span{display:block !important;text-align:center !important;background:transparent !important;border:none !important;box-shadow:none !important;color:#9C8E78 !important;letter-spacing:.2em !important;font-size:11.5px !important;padding:0 !important}
[data-wk="time"] > span::before{content:"Tonight" !important;display:block !important;font:italic 400 15px/1.4 Georgia,"Times New Roman",serif !important;letter-spacing:.06em !important;color:#EDE2CF !important;margin-bottom:2px !important}

/* 已读／已送达：中英两行字，字距拉开 */
[data-wk="meta"]{color:#9C8E78 !important;font-size:10px !important;letter-spacing:.2em !important}
[data-wk="meta"][data-read="0"]::before{content:"SENT" !important;font:500 9px/1 Georgia,serif !important;letter-spacing:.3em !important;margin-right:10px !important;color:#9C8E78 !important}
[data-wk="meta"][data-read="1"]::after{content:"READ" !important;font:500 9px/1 Georgia,serif !important;letter-spacing:.3em !important;margin-left:10px !important;color:#9C8E78 !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#2A1D17 !important;border:none !important;border-left:3px solid #C9A36A !important;border-radius:0 !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#E0353A !important}
[data-wk="name"]{color:#9C8E78 !important;letter-spacing:.25em !important;font-size:11px !important;margin-bottom:8px !important}
[data-wk="name"]::after{content:" ：" !important}
[data-wk="name"][data-me="1"],[data-wk="msg"][data-me="1"] [data-wk="name"]{display:none !important}

/* 动描：一块虚线框的字幕，左上贴一张「Voice-over」黑标签，字居中、字距松 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important;padding-top:12px !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:linear-gradient(90deg,rgba(20,16,13,.55),rgba(80,20,22,.35)) !important;border:1.2px dashed rgba(237,226,207,.55) !important;border-radius:0 !important;box-shadow:none !important;color:#EDE2CF !important;font-style:normal !important;font-size:13px !important;line-height:1.85 !important;letter-spacing:.18em !important;padding:20px 22px 14px !important;text-align:center !important;overflow:visible !important}
[data-wk="narrink"]::before{content:"Voice-over" !important;position:absolute !important;left:22px !important;top:-11px !important;padding:3px 26px !important;background:#14100D !important;font:italic 400 12px/1.2 Georgia,serif !important;letter-spacing:.14em !important;color:#EDE2CF !important}
/* 系统提示：一行小字，前面一道短红线 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9C8E78 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.18em !important}
[data-wk="sysnotetext"]::before{content:"" !important;display:inline-block !important;width:14px !important;height:1px !important;margin-right:8px !important;vertical-align:4px !important;background:#E0353A !important}
[data-wk="sysnoteclose"]{color:#9C8E78 !important}

/* 底栏：墨黑，上沿一道金线；上面一条录像带进度（红点走到三分之一）、右边 Track 01 舊夢 */
[data-wk="composer"]{background:#14100D !important;border-top:1px solid #8C7148 !important;position:relative !important;overflow:visible !important;align-items:center !important;gap:10px !important;padding-top:34px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:16px !important;top:10px !important;width:60% !important;height:12px !important;background:url("data:image/svg+xml;base64,") left center/100% 100% no-repeat !important;pointer-events:none !important}
[data-wk="composer"]::after{content:"/ Track 01  舊夢\A Vintage Record" !important;white-space:pre !important;position:absolute !important;right:16px !important;top:7px !important;text-align:right !important;font:italic 400 10.5px/1.35 Georgia,serif !important;color:#EDE2CF !important;pointer-events:none !important}
[data-wk="chatinput"]{background:linear-gradient(#EDE2CF,#EDE2CF) left top/10px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) left top/1.4px 10px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/10px 1.4px no-repeat,linear-gradient(#EDE2CF,#EDE2CF) right bottom/1.4px 10px no-repeat,rgba(237,226,207,.04) !important;border:1px solid rgba(237,226,207,.28) !important;border-radius:0 !important;color:#EDE2CF !important;letter-spacing:.12em !important;box-shadow:none !important}
[data-wk="chatinput"]::placeholder{color:#9C8E78 !important}
[data-wk="chatplus"],[data-wk="send"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA0MCc+PGNpcmNsZSBjeD0nMjAnIGN5PScyMCcgcj0nMTcuNScgZmlsbD0nbm9uZScgc3Ryb2tlPScjRURFMkNGJyBzdHJva2Utd2lkdGg9JzEuNCcvPjxwYXRoIGQ9J00yMCAxMiBWMjggTTEyIDIwIEgyOCcgc3Ryb2tlPScjRURFMkNGJyBzdHJva2Utd2lkdGg9JzEuNCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="send"]{width:46px !important;min-width:46px !important;height:46px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 0 8px rgba(224,53,58,.45)) !important}
[data-wk="chatreply"]{position:relative !important;width:64px !important;min-width:64px !important;height:36px !important;border:1px solid #EDE2CF !important;border-radius:0 !important;background:transparent !important;box-shadow:none !important}
[data-wk="chatreply"]::before{content:"回 覆" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;color:#EDE2CF !important;font-size:13px !important;letter-spacing:.2em !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
[data-wk="chatpanel"]{background:#14100D !important;border-top:1px solid #8C7148 !important}
